  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 8, 'g8_st2', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Nhận biết thay đổi cơ thể ở tuổi dậy thì và thói quen chăm sóc vệ sinh cá nhân.', '{"textWithBlanks":"Cơ thể có nhiều thay đổi về hình thái và sinh lí ở tuổi [blank].","bankWords":["dậy thì","sơ sinh mãi mãi","sau khi chết"],"hint":"Thử từng từ trong kho vào câu “Cơ thể có nhiều thay đổi về hình thái và sinh lí ở tuổi [blank].” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “d” và gồm 2 tiếng."}'::jsonb, '{"value":"dậy thì","explanation":"Từ đúng là “dậy thì”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 8 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 40. Sinh sản ở người"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
